/**
 * gen_gpu_registers.mjs — parse xenia's register_table.inc and emit
 * public/js/gpu/xenos_registers.js, the JS register table for the Xenos GPU.
 *
 * Usage:
 *   node tools/gen_gpu_registers.mjs [/path/to/register_table.inc]
 *
 * The .xenia-ref/ tree is a local, gitignored copy of xenia-canary (BSD-3).
 * The generated file is committed so the build does not depend on the ref.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = process.argv[2] ?? join(root, '.xenia-ref/gpu/register_table.inc');
const dst = join(root, 'public/js/gpu/xenos_registers.js');

const text = readFileSync(src, 'utf8');
const re = /^XE_GPU_REGISTER\((0x[0-9A-Fa-f]+),\s*(kDword|kFloat),\s*([A-Za-z0-9_]+)\)\s*$/gm;
const regs = [];
const seen = new Map();
let m;
while ((m = re.exec(text))) {
  const index = parseInt(m[1], 16);
  const type = m[2] === 'kDword' ? 0 : 1; // 0 = kDword, 1 = kFloat
  const name = m[3];
  if (seen.has(index)) throw new Error(`duplicate register index 0x${index.toString(16)} (${seen.get(index)} vs ${name})`);
  seen.set(index, name);
  regs.push([index, type, name]);
}
regs.sort((a, b) => a[0] - b[0]);
const maxIndex = Math.max(...regs.map(([i]) => i));
console.log(`parsed ${regs.length} registers, max index 0x${maxIndex.toString(16)}`);

const lines = [
  '/**',
  ' * xenos_registers.js — GENERATED by tools/gen_gpu_registers.mjs from xenia-canary register_table.inc (BSD-3).',
  ' * Do not edit by hand; regenerate with: node tools/gen_gpu_registers.mjs',
  ' *',
  ' * Entry shape: [dwordIndex, type, name] — type 0 = kDword, 1 = kFloat.',
  ` * Register count: ${regs.length}; highest index: 0x${maxIndex.toString(16)}.`,
  ' */',
  '(function (global) {',
  "  'use strict';",
  '  // prettier-ignore',
  '  const XENOS_GPU_REGISTERS = Object.freeze([',
  ...regs.map(([i, t, n]) => `    [0x${i.toString(16).padStart(4, '0')}, ${t}, '${n}'],`),
  '  ]);',
  '  const BY_INDEX = new Map();',
  '  const BY_NAME = new Map();',
  '  for (const [index, type, name] of XENOS_GPU_REGISTERS) {',
  '    BY_INDEX.set(index, { index, type, name });',
  '    BY_NAME.set(name, { index, type, name });',
  '  }',
  '  // Hardware reset defaults (AMD R6xx/R7xx 3D reference + Mesa r600g, mirrored in xenia\'s RegisterFile).',
  '  const RESET_DEFAULTS = Object.freeze({',
  '    VGT_MAX_VTX_INDX: 0x0000FFFF,',
  '    VGT_MULTI_PRIM_IB_RESET_INDX: 0x0000FFFF,',
  '    PA_SC_SCREEN_SCISSOR_BR: 0x20002000,',
  '    RB_STENCILREFMASK_BF: 0x00FFFF00,',
  '    PA_SU_POINT_SIZE: 0x00080008,',
  '    PA_SU_POINT_MINMAX: 0x04000010,',
  '    PA_SU_LINE_CNTL: 0x00000008,',
  '    PA_SC_LINE_CNTL: 0x00000400,',
  '    VGT_HOS_REUSE_DEPTH: 0x0000000E,',
  '    VGT_VERTEX_REUSE_BLOCK_CNTL: 0x0000000E,',
  '    VGT_OUT_DEALLOC_CNTL: 0x00000010,',
  '    PA_CL_GB_VERT_CLIP_ADJ: 0x40000000,',
  '    PA_CL_GB_VERT_DISC_ADJ: 0x3F800000,',
  '    PA_CL_GB_HORZ_CLIP_ADJ: 0x40000000,',
  '    PA_CL_GB_HORZ_DISC_ADJ: 0x3F800000,',
  '    PA_SC_AA_MASK: 0x0000FFFF,',
  '  });',
  '  const api = {',
  '    XENOS_GPU_REGISTERS,',
  '    XENOS_GPU_REGISTER_BY_INDEX: BY_INDEX,',
  '    XENOS_GPU_REGISTER_BY_NAME: BY_NAME,',
  '    XENOS_GPU_RESET_DEFAULTS: RESET_DEFAULTS,',
  '    XENOS_GPU_REGISTER_COUNT: 0x5003,',
  '  };',
  "  if (typeof module !== 'undefined' && module.exports) module.exports = api;",
  "  global.XenonGpuRegisters = api;",
  "})(typeof self !== 'undefined' ? self : globalThis);",
  '',
];
writeFileSync(dst, lines.join('\n'));
console.log('wrote', dst);
